package dev.aibuilder;

import org.junit.jupiter.api.Test;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import static org.junit.jupiter.api.Assertions.*;

/** Real geometry checks: no fixed castle is ever generated by this auditor. */
final class CastleStructureAuditTest {
    private static final String REQUEST=
        "Построй готический замок с четырьмя мощными угловыми башнями "
        +"и главными воротами с большой каменной аркой.";

    private static List<ArchitectureSpec.Region> regions(){
        List<ArchitectureSpec.Region> r=new ArrayList<>();
        int[][] points={{2,2},{27,2},{2,27},{27,27}};
        for(int i=0;i<4;i++)
            r.add(new ArchitectureSpec.Region("tower_"+i,"tower",
                points[i][0],1,points[i][1],5,11,5,List.of("gate")));
        r.add(new ArchitectureSpec.Region("gate","gatehouse",
            14,1,2,5,6,3,List.of("tower_0","tower_1")));
        return r;
    }

    private static Map<WalkabilityAudit.Cell,String> complete(){
        Map<WalkabilityAudit.Cell,String> blocks=new HashMap<>();
        for(var r:regions()){
            if(!r.kind().equals("tower"))continue;
            for(int y=r.y();y<r.y()+r.height();y++)
                for(int x=r.x();x<r.x()+r.width();x++)
                    for(int z=r.z();z<r.z()+r.depth();z++)
                        if(x==r.x()||x==r.x()+r.width()-1||
                           z==r.z()||z==r.z()+r.depth()-1)
                            blocks.put(new WalkabilityAudit.Cell(x,y,z),"stone_bricks");
        }
        // 3x3 gate with two actual supporting columns on either side.
        for(int y=1;y<=4;y++){
            blocks.put(new WalkabilityAudit.Cell(14,y,3),"stone_bricks");
            blocks.put(new WalkabilityAudit.Cell(18,y,3),"stone_bricks");
        }
        return blocks;
    }

    @Test void requestedFourActualTowersAndWideGatePass(){
        var check=CastleStructureAudit.inspect(REQUEST,regions(),complete());
        assertTrue(check.canBuild(),check.blockers().toString());
    }

    @Test void exactlyTheBadScreenshotSituationSmallSideDoorCannotPassAsGrandGate(){
        var blocks=complete();
        for(int y=1;y<=3;y++){
            blocks.remove(new WalkabilityAudit.Cell(14,y,3));
            blocks.remove(new WalkabilityAudit.Cell(18,y,3));
            blocks.put(new WalkabilityAudit.Cell(15,y,3),"stone_bricks");
            blocks.put(new WalkabilityAudit.Cell(17,y,3),"stone_bricks");
            blocks.put(new WalkabilityAudit.Cell(16,y,3),"oak_door");
        }
        var result=CastleStructureAudit.inspect(REQUEST,regions(),blocks);
        assertFalse(result.canBuild());
        assertTrue(result.blockers().stream().anyMatch(s->s.contains("ворота")),
            result.blockers().toString());
    }

    @Test void missingActualStoneTowersAreNotExcusedByFourTowerJsonLabels(){
        var blocks=complete();
        blocks.entrySet().removeIf(e->e.getKey().x()>=27 && e.getKey().z()>=27);
        var result=CastleStructureAudit.inspect(REQUEST,regions(),blocks);
        assertFalse(result.canBuild());
        assertTrue(result.blockers().stream().anyMatch(s->s.contains("Башня")),
            result.blockers().toString());
    }

    @Test void noArchitecturalRegionsIsNotEnoughForAProfessionalCastle(){
        var result=CastleStructureAudit.inspect(REQUEST,List.of(),complete());
        assertFalse(result.canBuild());
        assertTrue(result.blockers().getFirst().contains("architecture.regions"));
    }

    @Test void missingSemanticTowerCountBlocksARequestForFourTowers(){
        var result=CastleStructureAudit.inspect(REQUEST,
            regions().subList(0,3),complete());
        assertFalse(result.canBuild());
        assertTrue(result.blockers().stream().anyMatch(s->s.contains("Запрошено 4")),
            result.blockers().toString());
    }

    @Test void otherArchitecturalStylesRemainUnaffected(){
        var result=CastleStructureAudit.inspect(
            "Построй современную виллу со стеклянными окнами",
            List.of(),Map.of());
        assertTrue(result.canBuild());
    }

    @Test void russianInflectionsAreActuallyRecognized(){
        assertEquals(4,RequestedFeatures.towers(
            "Замок с четырьмя мощными угловыми башнями"));
        assertEquals(4,RequestedFeatures.towers(
            "Построй четыре мощные угловые башни"));
        assertEquals(5,RequestedFeatures.towers(
            "Построй пять высоких башен"));
        assertEquals(3,RequestedFeatures.towers(
            "Построй 3 круглых башни"));
    }
}
